SELECT
  CASE WHEN (CAST(SUBSTR('2023-03-01', 6, 2) AS INTEGER) = 2) THEN CASE WHEN ((((((CAST(SUBSTR('2023-03-01', 1, 4) AS INTEGER)) - (4) * CAST((CAST(SUBSTR('2023-03-01', 1, 4) AS INTEGER)) / NULLIF(4, 0) AS INTEGER))) = 0) AND ((((CAST(SUBSTR('2023-03-01', 1, 4) AS INTEGER)) - (100) * CAST((CAST(SUBSTR('2023-03-01', 1, 4) AS INTEGER)) / NULLIF(100, 0) AS INTEGER))) != 0)) OR ((((CAST(SUBSTR('2023-03-01', 1, 4) AS INTEGER)) - (400) * CAST((CAST(SUBSTR('2023-03-01', 1, 4) AS INTEGER)) / NULLIF(400, 0) AS INTEGER))) = 0)) THEN 29 ELSE 28 END ELSE (CASE WHEN ((CAST(SUBSTR('2023-03-01', 6, 2) AS INTEGER)) - (1)) < 0 THEN NULL ELSE JSON_EXTRACT(JSON_ARRAY(31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31), '$[' || ((CAST(SUBSTR('2023-03-01', 6, 2) AS INTEGER)) - (1)) || ']') END) END AS n;